export function parseLayout(comment) {
  if (typeof comment !== 'string' || /[^\t\x20-\x7e]/.test(comment)) return null;
  const match = /^<!--md-layout:v1[ \t]+([^\r\n]*?)[ \t]*-->$/.exec(comment);
